{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "ACT001, a terpenoid lactone, reached brain concentrations higher than plasma after oral dosing in rats, directly demonstrating CNS access for a lactone-containing natural product.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Pd-Ia, a low-polarity lactone/acetate, was detected in rat brain at 2.04 µg/g after i.v. dosing, indicating BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Bufotalin, a bufadienolide lactone, showed brain concentrations significantly higher than blood in mice, confirming meaningful BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Bufalin, a related bufadienolide, was primarily distributed to brain after i.v. delivery in mice with prolonged brain retention.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Methylprednisolone showed low unidirectional blood-to-brain transport via a saturable/transporter-mediated mechanism, providing a single contradictory example of limited CNS access in a more polar steroid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted pass: multiple high-transfer direct brain-penetration measurements in terpenoid/steroid lactones (brain > plasma or detectable brain levels) strongly outweigh the single transporter-limited corticosteroid example; the query's furan-containing lactone/ester scaffold is consistent with CNS-permeable natural products.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query itself.",
    "P-gp/BCRP efflux liability not directly assessed for the query.",
    "Possible ester hydrolysis/prodrug behavior in vivo not characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

